        let profile = normalize_rustup_profile(profile)?;
        let Some((toolchain, manifest)) = self.rustup_toolchain_manifest(tv, runtime)? else {
            return Ok(fallback_rustup_profile_components(profile));
        };
        match parse_rustup_profile_components(&manifest, &toolchain, profile) {
            Ok(components) => Ok(Some(components)),
            Err(err) => {
                debug!(
